package com.orderflow.notification.service;
import com.orderflow.events.EventMetadata;import com.orderflow.events.EventType;import com.orderflow.events.NotificationDispatchRequestedEvent;import com.orderflow.notification.config.KafkaTopicProperties;import com.orderflow.notification.config.NotificationReconciliationProperties;import com.orderflow.notification.domain.NotificationDeliveryStatus;import com.orderflow.notification.outbox.OutboxStore;import com.orderflow.notification.repository.NotificationDeliveryRepository;import com.orderflow.notification.repository.NotificationRepository;import java.time.Clock;import java.time.Instant;import java.util.UUID;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class NotificationReconciliationService{private final NotificationDeliveryRepository deliveries;private final NotificationRepository notifications;private final NotificationReconciliationProperties properties;private final OutboxStore outbox;private final KafkaTopicProperties topics;private final Clock clock;public NotificationReconciliationService(NotificationDeliveryRepository d,NotificationRepository n,NotificationReconciliationProperties p,OutboxStore o,KafkaTopicProperties t,Clock c){deliveries=d;notifications=n;properties=p;outbox=o;topics=t;clock=c;}@Transactional public Outcome recover(UUID id,String correlation){var d=deliveries.lockById(id).orElse(null);Instant now=Instant.now(clock);if(d==null||d.getStatus()!=NotificationDeliveryStatus.PROCESSING||!d.getUpdatedAt().isBefore(now.minus(properties.staleThreshold())))return Outcome.UNCHANGED;if(d.getAttemptCount()>=properties.maxAttempts()){d.failed(now,"RECONCILIATION_ATTEMPTS_EXHAUSTED");return Outcome.FAILED;}var n=notifications.findById(d.getNotificationId()).orElseThrow();d.retry(now,"STALE_PROCESSING_RECOVERED");EventMetadata m=new EventMetadata(UUID.randomUUID(),EventType.NOTIFICATION_DISPATCH_REQUESTED,NotificationDispatchRequestedEvent.VERSION,"NOTIFICATION",n.getId(),now,correlation,null,"notification-service");var event=new NotificationDispatchRequestedEvent(m,n.getId(),n.getUserId(),d.getChannel().name(),d.getId());outbox.enqueue(topics.notificationEvents(),n.getId(),event,m);return Outcome.RECOVERED;}public enum Outcome{RECOVERED,FAILED,UNCHANGED}}
